// ─── Constants ────────────────────────────────────────────

const DISCLAIMER =
  "This is an AI-generated estimate based on available historical data and statistical analysis. It is not an established fact and should be used as a reference only. Always verify with on-the-ground assessment.";

const DEFAULT_EXPIRY_HOURS = 24;

// ─── Risk Helpers ─────────────────────────────────────────

function scoreToConfidence(score: number): ConfidenceLevel {
  if (score >= 90) return "very_high";
  if (score >= 75) return "high";
  if (score >= 50) return "moderate";
  if (score >= 25) return "low";
  return "very_low";
}

function scoreToSeverity(score: number): RiskSeverity {
  if (score >= 80) return "critical";
  if (score >= 60) return "high";
  if (score >= 35) return "medium";
  return "low";
}

function generateExpiry(hours = DEFAULT_EXPIRY_HOURS): string {
  return new Date(Date.now() + hours * 60 * 60 * 1000).toISOString();
}

function clamp(value: number, min = 0, max = 100): number {
  return Math.max(min, Math.min(max, value));
}

function randomBetween(min: number, max: number): number {
  return Math.round((min + Math.random() * (max - min)) * 10) / 10;
}

// ─── Model Registry (in-memory) ──────────────────────────

class ModelRegistry {
  private models: Map<string, PredictionModel> = new Map();

  register(model: PredictionModel): void {
    this.models.set(model.id, model);
  }

  get(id: string): PredictionModel | undefined {
    return this.models.get(id);
  }

  getByCategory(category: string): PredictionModel[] {
    return Array.from(this.models.values()).filter(
      (m) => m.category === category && m.status === "active"
    );
  }

  getAll(): PredictionModel[] {
    return Array.from(this.models.values());
  }

  getOnlineCount(): number {
    return Array.from(this.models.values()).filter(
      (m) => m.status === "active"
    ).length;
  }

  getTrainingCount(): number {
    return Array.from(this.models.values()).filter(
      (m) => m.status === "training"
    ).length;
  }
}

